const commits = $('Fetch Commits Per Repo').all().map(i => ({
  repo: i.json.repo,
  sha: i.json.sha?.slice(0, 7),
  message: i.json.commit?.message,
  date: i.json.commit?.author?.date,
  author: i.json.commit?.author?.name
})).filter(c => c.message);

const issues = $('Fetch Closed Issues Per Repo').all().map(i => ({
  repo: i.json.repo,
  number: i.json.number,
  title: i.json.title,
  body: i.json.body?.slice(0, 300),
  closedAt: i.json.closed_at
})).filter(i => i.title);

const today = $('Set Config').first().json.today;

return [{ json: { commits, issues, today, repoList: [...new Set(commits.map(c => c.repo))] } }];

const text = $input.first().json.content?.[0]?.text ?? '';
const today = $('Build Claude Prompt').first().json.today;

if (!text.trim().startsWith('---')) {
  throw new Error('Claude response did not start with YAML frontmatter (---).');
}

const filename = `${today}-weekly-dev-log.md`;
const remotePath = `/srv/zackdell.com/repo/src/content/blog/${filename}`;

return [{ json: { markdown: text, filename, remotePath } }];

